begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into public.courses(id,owner_id,title) values ('96000000-0000-0000-0000-000000000001','11111111-1111-1111-1111-111111111111','Summary test');
insert into public.chat_conversations(id,course_id) values ('96000000-0000-0000-0000-000000000002','96000000-0000-0000-0000-000000000001');
select public.append_chat_exchange('96000000-0000-0000-0000-000000000002',gen_random_uuid(),'Frage','Antwort','test');
create temporary table summary_lease as select (public.reserve_chat_request('11111111-1111-1111-1111-111111111111','96000000-0000-0000-0000-000000000002','96000000-0000-0000-0000-000000000003','Weiter','openai','test',100,10)->>'lease_token')::uuid as token;
grant select on summary_lease to authenticated,service_role;
set local role service_role;
select is(public.save_chat_history_summary('11111111-1111-1111-1111-111111111111','96000000-0000-0000-0000-000000000002','96000000-0000-0000-0000-000000000003',(select token from summary_lease),0,2,'Kontext'),true,'Valid lease stores summary');
select is(public.save_chat_history_summary('11111111-1111-1111-1111-111111111111','96000000-0000-0000-0000-000000000002','96000000-0000-0000-0000-000000000003',(select token from summary_lease),0,2,'Kontext'),false,'Stale cursor cannot overwrite progress');
select throws_ok($$select public.save_chat_history_summary('11111111-1111-1111-1111-111111111111','96000000-0000-0000-0000-000000000002','96000000-0000-0000-0000-000000000003',(select token from summary_lease),2,3,'Kontext')$$,'22023','INVALID_CHAT_SUMMARY','Cannot summarize missing messages');
select throws_ok($$select public.save_chat_history_summary('11111111-1111-1111-1111-111111111111','96000000-0000-0000-0000-000000000002','96000000-0000-0000-0000-000000000003',(select token from summary_lease),2,2,'Kontext')$$,'22023','INVALID_CHAT_SUMMARY','Cursor cannot move backwards');
select throws_ok($$select public.save_chat_history_summary('11111111-1111-1111-1111-111111111111','96000000-0000-0000-0000-000000000002','96000000-0000-0000-0000-000000000003',gen_random_uuid(),0,2,'Kontext')$$,'P0001','REQUEST_LEASE_EXPIRED','Stale worker fenced');
select throws_ok($$select public.save_chat_history_summary('22222222-2222-2222-2222-222222222222','96000000-0000-0000-0000-000000000002','96000000-0000-0000-0000-000000000003',(select token from summary_lease),0,2,'Kontext')$$,'P0002','CONVERSATION_NOT_FOUND','Foreign owner rejected');
reset role;
update public.chat_requests set lease_until=now()-interval '1 second' where conversation_id='96000000-0000-0000-0000-000000000002';
set local role service_role;
select throws_ok($$select public.save_chat_history_summary('11111111-1111-1111-1111-111111111111','96000000-0000-0000-0000-000000000002','96000000-0000-0000-0000-000000000003',(select token from summary_lease),0,2,'Kontext')$$,'P0001','REQUEST_LEASE_EXPIRED','Expired lease fenced');
set local role authenticated;
set local request.jwt.claims = '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated"}';
select is((select content from public.chat_history_summaries where conversation_id='96000000-0000-0000-0000-000000000002'),'Kontext','Owner reads summary');
select throws_ok($$update public.chat_history_summaries set content='Fake'$$,'42501',null,'Clients cannot write summaries');
select throws_ok($$select public.save_chat_history_summary('11111111-1111-1111-1111-111111111111','96000000-0000-0000-0000-000000000002','96000000-0000-0000-0000-000000000003',(select token from summary_lease),0,2,'Kontext')$$,'42501',null,'Clients cannot call summary RPC');
set local request.jwt.claims = '{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated"}';
select is((select count(*)::int from public.chat_history_summaries),0,'Foreign summaries hidden');
reset role;
select is((select count(*)::int from public.chat_messages where conversation_id='96000000-0000-0000-0000-000000000002'),2,'Original messages preserved');
delete from public.chat_conversations where id='96000000-0000-0000-0000-000000000002';
select is((select count(*)::int from public.chat_history_summaries where conversation_id='96000000-0000-0000-0000-000000000002'),0,'Summary deleted with conversation');
select * from finish();
rollback;
